    stockIntersectionAnalysis = pgTable34("stock_intersection_analysis", {
      id: uuid5("id").primaryKey().defaultRandom(),
      portfolioId: uuid5("portfolio_id"),
      prospectId: uuid5("prospect_id"),
      userId: uuid5("user_id"),
      analysisDate: timestamp34("analysis_date").defaultNow(),
      totalFundsAnalyzed: integer33("total_funds_analyzed").default(0),
      totalStocksFound: integer33("total_stocks_found").default(0),
      overlappingStocksCount: integer33("overlapping_stocks_count").default(0),
      highRiskStocksCount: integer33("high_risk_stocks_count").default(0),
      mediumRiskStocksCount: integer33("medium_risk_stocks_count").default(0),
      stockOverlaps: jsonb34("stock_overlaps"),
      sectorConcentration: jsonb34("sector_concentration"),
      diversificationScore: decimal34("diversification_score", { precision: 5, scale: 2 }),
      createdAt: timestamp34("created_at").defaultNow(),
      updatedAt: timestamp34("updated_at").defaultNow()
    }, (table) => ({
      portfolioIdIdx: index31("stock_intersection_portfolio_id_idx").on(table.portfolioId),
      prospectIdIdx: index31("stock_intersection_prospect_id_idx").on(table.prospectId),
      userIdIdx: index31("stock_intersection_user_id_idx").on(table.userId),
      analysisDateIdx: index31("stock_intersection_analysis_date_idx").on(table.analysisDate)
    }));
