    bankEligibilityRules = pgTable34("bank_eligibility_rules", {
      id: varchar34("id").primaryKey().default(sql34`gen_random_uuid()`),
      // Bank & Product
      bankCode: varchar34("bank_code").notNull(),
      // ICICI, HDFC, AXIS, KOTAK, SBI, BAJAJ, TATA
      productType: varchar34("product_type").notNull(),
      // personal, business, home, lap, car, education, gold, securities
      // Employment Eligibility
      allowedEmploymentTypes: text33("allowed_employment_types").array().default([]),
      // ['salaried', 'self_employed', 'professional', 'business_owner']
      // Credit Score Requirements
      minCibilScore: integer33("min_cibil_score").default(650),
      maxCibilScore: integer33("max_cibil_score").default(900),
      // Income Requirements
      minMonthlyIncome: decimal34("min_monthly_income", { precision: 12, scale: 2 }).default("20000"),
      maxMonthlyIncome: decimal34("max_monthly_income", { precision: 12, scale: 2 }),
      // Business Loan Specific
      minBusinessVintageMonths: integer33("min_business_vintage_months"),
      // Minimum business age in months
      minAnnualTurnover: decimal34("min_annual_turnover", { precision: 15, scale: 2 }),
      // Loan Parameters
      minLoanAmount: decimal34("min_loan_amount", { precision: 15, scale: 2 }).default("50000"),
      maxLoanAmount: decimal34("max_loan_amount", { precision: 15, scale: 2 }),
      minTenureMonths: integer33("min_tenure_months").default(12),
      maxTenureMonths: integer33("max_tenure_months").default(60),
      // LAP/Home Loan Specific
      allowedPropertyTypes: text33("allowed_property_types").array().default([]),
      // ['residential', 'commercial', 'mixed']
      maxLtvRatio: decimal34("max_ltv_ratio", { precision: 5, scale: 2 }),
      // Loan-to-Value ratio
      // Age Requirements
      minAge: integer33("min_age").default(21),
      maxAge: integer33("max_age").default(60),
      // Geographic Restrictions
      allowedCities: text33("allowed_cities").array().default([]),
      // Empty = all cities
      excludedCities: text33("excluded_cities").array().default([]),
      // Routing Priority (lower = higher priority)
      routingPriority: integer33("routing_priority").default(100),
      // Status & Notes
      isActive: boolean34("is_active").default(true),
      notes: text33("notes"),
      createdAt: timestamp34("created_at").defaultNow(),
      updatedAt: timestamp34("updated_at").defaultNow()
    });
