      tdsDeducted: decimal34("tds_deducted", { precision: 15, scale: 2 }),
      advanceTaxPaid: decimal34("advance_tax_paid", { precision: 15, scale: 2 }),
      selfAssessmentTax: decimal34("self_assessment_tax", { precision: 15, scale: 2 }),
