      // Market Change: { type: 'percent_gain', value: 5 } or { type: 'percent_loss', value: 3 }
      // Spending: { type: 'category_limit', category: 'food', period: 'monthly', value: 10000 }
      // Portfolio: { type: 'value_below', value: 500000 }
      // Spending alert specific fields
      spendingCategory: varchar34("spending_category"),
      // 'food', 'transport', 'entertainment', 'utilities', 'shopping', 'healthcare', etc.
      spendingPeriod: varchar34("spending_period"),
      // 'daily', 'weekly', 'monthly', 'yearly'
      // Notification preferences
      notificationChannels: jsonb34("notification_channels").default(["email"]),
      // ['email', 'whatsapp', 'sms', 'push', 'in_app']
      // Alert status and controls
      isActive: boolean34("is_active").default(true),
      priority: varchar34("priority").default("medium"),
      // 'high', 'medium', 'low'
      // Frequency controls (prevent spam)
      cooldownPeriod: integer33("cooldown_period").default(3600),
      // Seconds between repeated alerts (default 1 hour)
      lastTriggeredAt: timestamp34("last_triggered_at"),
      triggerCount: integer33("trigger_count").default(0),
      // Metadata
