    platformFeeConfig = pgTable34("platform_fee_config", {
      id: varchar34("id").primaryKey().default(sql34`gen_random_uuid()`),
      // Fee Identification
      feeCode: varchar34("fee_code", { length: 50 }).notNull().unique(),
      feeName: varchar34("fee_name", { length: 100 }).notNull(),
      feeDescription: text33("fee_description"),
      category: varchar34("category", { length: 50 }).notNull(),
      // regulatory, platform, advisory, etc.
      // Charge Structure
      chargeType: varchar34("charge_type", { length: 20 }).notNull().default("percentage"),
      rateValue: decimal34("rate_value", { precision: 12, scale: 6 }).notNull(),
      // Rate or flat amount
      rateUnit: varchar34("rate_unit", { length: 20 }).default("percent"),
      // percent, bps, inr
      minAmount: decimal34("min_amount", { precision: 10, scale: 2 }).default("0"),
      maxAmount: decimal34("max_amount", { precision: 10, scale: 2 }),
      // Cap if applicable
      // Tiered Pricing (for tiered charge type)
      tierSlabs: jsonb34("tier_slabs"),
      // [{from: 0, to: 100000, rate: 0.5}, {from: 100001, to: 500000, rate: 0.3}]
      // Applicability
      applicableTo: varchar34("applicable_to", { length: 50 }).notNull().default("all"),
      applicableProducts: text33("applicable_products").array(),
      // Specific product codes
      excludedProducts: text33("excluded_products").array(),
      // Investor Tier Pricing
      investorTierRates: jsonb34("investor_tier_rates"),
      // {retail: 0.5, sHNI: 0.35, bHNI: 0.25, qib: 0.1}
      // GST Applicability
      isGstApplicable: boolean34("is_gst_applicable").default(true),
      gstRate: decimal34("gst_rate", { precision: 5, scale: 2 }).default("18"),
      gstIncluded: boolean34("gst_included").default(false),
      // Is GST already included in rate?
      // Payer and Collection
      payer: varchar34("payer", { length: 20 }).default("client"),
      // client, platform, seller, both
      collectionPoint: varchar34("collection_point", { length: 50 }).default("transaction"),
      // transaction, monthly, annual
      // Regulatory Reference
      isRegulatory: boolean34("is_regulatory").default(false),
      regulatoryReference: varchar34("regulatory_reference", { length: 200 }),
      statuteSection: varchar34("statute_section", { length: 200 }),
      // Waivers and Discounts
      isWaivable: boolean34("is_waivable").default(false),
      maxWaiverPercent: decimal34("max_waiver_percent", { precision: 5, scale: 2 }).default("0"),
      // Display
      displayOrder: integer33("display_order").default(100),
      showInBreakdown: boolean34("show_in_breakdown").default(true),
      displayLabel: varchar34("display_label", { length: 100 }),
      // User-friendly label
      // Status and Validity
      isActive: boolean34("is_active").default(true),
      effectiveFrom: timestamp34("effective_from").defaultNow(),
      effectiveTo: timestamp34("effective_to"),
      // Audit Trail
      createdAt: timestamp34("created_at").defaultNow().notNull(),
      updatedAt: timestamp34("updated_at").defaultNow().notNull(),
      createdBy: varchar34("created_by").references(() => users.id),
      updatedBy: varchar34("updated_by").references(() => users.id)
    }, (table) => [
      index31("idx_fee_config_code").on(table.feeCode),
      index31("idx_fee_config_category").on(table.category),
      index31("idx_fee_config_applicable").on(table.applicableTo),
      index31("idx_fee_config_active").on(table.isActive)
    ]);
