    errorLedger = pgTable34("error_ledger", {
      id: varchar34("id").primaryKey().default(sql34`gen_random_uuid()`),
      // Error Classification
      errorCode: varchar34("error_code", { length: 100 }).notNull(),
      severity: varchar34("severity", { length: 20 }).notNull().default("error"),
      source: varchar34("source", { length: 20 }).notNull(),
      module: varchar34("module", { length: 50 }).notNull(),
      // Error Details
      message: text33("message").notNull(),
      stackHash: varchar34("stack_hash", { length: 64 }),
      stackTrace: text33("stack_trace"),
      // Context (business-aware)
      clientId: varchar34("client_id").references(() => users.id),
      agentId: varchar34("agent_id").references(() => users.id),
      panMasked: varchar34("pan_masked", { length: 20 }),
      transactionId: varchar34("transaction_id", { length: 100 }),
      requestId: varchar34("request_id", { length: 100 }),
      // User Agent & Environment
      userAgent: text33("user_agent"),
      ipAddress: varchar34("ip_address", { length: 45 }),
      url: text33("url"),
      httpMethod: varchar34("http_method", { length: 10 }),
      httpStatus: integer33("http_status"),
      // External Tracking
      sentryEventId: varchar34("sentry_event_id", { length: 100 }),
      // Status & Resolution
      status: varchar34("status", { length: 20 }).default("open"),
      acknowledgedBy: varchar34("acknowledged_by").references(() => users.id),
      acknowledgedAt: timestamp34("acknowledged_at"),
      resolvedBy: varchar34("resolved_by").references(() => users.id),
      resolvedAt: timestamp34("resolved_at"),
      resolutionNote: text33("resolution_note"),
      // Occurrence Tracking
      occurrenceCount: integer33("occurrence_count").default(1),
      firstOccurrence: timestamp34("first_occurrence").defaultNow(),
      lastOccurrence: timestamp34("last_occurrence").defaultNow(),
      // Environment
      environment: varchar34("environment", { length: 20 }).default("production"),
      buildVersion: varchar34("build_version", { length: 50 }),
      // Metadata
      metadata: jsonb34("metadata"),
      createdAt: timestamp34("created_at").defaultNow(),
      updatedAt: timestamp34("updated_at").defaultNow()
    }, (table) => [
      index31("idx_error_ledger_severity").on(table.severity),
      index31("idx_error_ledger_status").on(table.status),
      index31("idx_error_ledger_module").on(table.module),
      index31("idx_error_ledger_error_code").on(table.errorCode),
      index31("idx_error_ledger_client").on(table.clientId),
      index31("idx_error_ledger_agent").on(table.agentId),
      index31("idx_error_ledger_created").on(table.createdAt),
      index31("idx_error_ledger_sentry").on(table.sentryEventId),
      index31("idx_error_ledger_stack_hash").on(table.stackHash)
    ]);
